/**
 * relocate-map-rendering.test.js
 *
 * Regression tests for the Batch Relocation Map shelf-button rendering bug.
 *
 * Root cause (this fix):
 *   The base `button { color: white }` rule in styles.css cascades onto every
 *   <button> in the page, including `.relocate-shelf-btn` buttons generated by
 *   renderRelocateMap(). The `.relocate-shelf-btn` rule overrode `background`
 *   (set to white) but never declared `color`, so shelf buttons displayed
 *   white text on a white background — invisible to the user. The rendered
 *   buttons were present in the DOM and occupied space (causing the large
 *   blank gaps between rack headings), but their text was unreadable.
 *
 * Fix (this commit):
 *   Added `color: var(--ink)` to `.relocate-shelf-btn` and
 *   `color: var(--ink)` to `.relocate-shelf-btn:hover`.
 *
 * Tests:
 *   CSS-level (no browser needed):
 *     1. Base `button` rule declares `color: white`.
 *     2. `.relocate-shelf-btn` rule explicitly declares `color` — override present.
 *     3. `.relocate-shelf-btn` color value is not `white` / `#fff` / `#ffffff`.
 *     4. `.relocate-shelf-btn:hover` explicitly declares `color`.
 *     5. `.relocate-shelf-btn.selected` keeps `color: white` (intentional).
 *     6. `.relocate-shelf-btn.current-location` does not set a light-on-light color.
 *
 *   DOM-level (jsdom, live renderRelocateMap() from public/app.js):
 *     7.  All 14 canonical shelf IDs render as buttons.
 *     8.  Every button carries a non-empty `data-relocate-shelf` attribute.
 *     9.  Button text content equals the shelf ID (not blank).
 *     10. All 5 rack groups render (RACK_A, RACK_B, RACK_C, RACK_D, RACK_COLD).
 *     11. Each rack card contains only its own shelves.
 *     12. `data-rack` attribute is set on every rack card.
 *     13. `current-location` class is applied to the correct button only.
 *     14. `selectRelocateShelf()` adds `selected` class and enables Save button.
 */

'use strict';

const { test } = require('node:test');
const assert   = require('node:assert/strict');
const fs       = require('node:fs');
const path     = require('node:path');
const { JSDOM } = require('jsdom');

// ── File paths ───────────────────────────────────────────────────────────────

const STYLES_PATH = path.join(__dirname, '..', 'public', 'styles.css');
const APP_JS_PATH = path.join(__dirname, '..', 'public', 'app.js');

// ── CSS text helpers ─────────────────────────────────────────────────────────

/**
 * Extract the raw declaration block for a given CSS selector (e.g.
 * ".relocate-shelf-btn {" → returns everything between the braces, exclusive).
 * Matches the FIRST occurrence — call-site must provide a specific-enough
 * selector string. Returns null if not found.
 */
function extractCssBlock(css, selectorLine) {
  const idx = css.indexOf(selectorLine);
  if (idx === -1) return null;
  // Walk to opening brace (handles selectors with a space before {)
  let i = idx;
  while (i < css.length && css[i] !== '{') i++;
  const start = i + 1;
  // Walk to matching close brace
  let depth = 1;
  i++;
  while (i < css.length && depth > 0) {
    if (css[i] === '{') depth++;
    else if (css[i] === '}') depth--;
    i++;
  }
  return css.slice(start, i - 1);
}

/**
 * Returns true when the CSS block contains an explicit `color:` declaration.
 */
function hasColorDeclaration(block) {
  // Match  color: <anything>;  not preceded by "background-" or "border-"
  return /(?<![a-z-])color\s*:/i.test(block);
}

/**
 * Returns the declared color value for a CSS block, or null.
 * Only reads the FIRST `color:` declaration that isn't a background/border-color.
 */
function getColorValue(block) {
  const m = block.match(/(?<![a-z-])color\s*:\s*([^;]+);/i);
  return m ? m[1].trim().toLowerCase() : null;
}

// ── JS extraction helpers (mirrors map-loading.test.js approach) ─────────────

const appJsSrc = fs.readFileSync(APP_JS_PATH, 'utf8');

function extractFunctionBody(src, funcSignature) {
  const idx = src.indexOf(funcSignature);
  if (idx === -1) throw new Error(`Function not found: ${funcSignature}`);
  let depth = 0, i = idx, bodyStart = -1, bodyEnd = -1;
  while (i < src.length) {
    if (src[i] === '{') { if (depth === 0) bodyStart = i + 1; depth++; }
    else if (src[i] === '}') { depth--; if (depth === 0) { bodyEnd = i; break; } }
    i++;
  }
  if (bodyEnd === -1) throw new Error('Could not find closing brace for: ' + funcSignature);
  return src.slice(bodyStart, bodyEnd);
}

const escapeHtmlBody          = extractFunctionBody(appJsSrc, 'function escapeHtml(');
const renderRelocateMapBody   = extractFunctionBody(appJsSrc, 'async function renderRelocateMap()');
const selectRelocateShelfBody = extractFunctionBody(appJsSrc, 'function selectRelocateShelf(');

const escapeHtml = new Function('value', escapeHtmlBody);

// Patch storeMapData references to use a ref-box (same technique as map-loading.test.js)
const patchedRenderBody = renderRelocateMapBody
  .replace(/\bstoreMapData\b/g, 'storeMapData_ref.current');

const AsyncFunction = Object.getPrototypeOf(async function(){}).constructor;
const renderRelocateMap_live = new AsyncFunction(
  'document',
  'storeMapData_ref',
  'relocateBatchState',
  'escapeHtml',
  'loadStoreMapView',
  patchedRenderBody
);

// selectRelocateShelf references module-level `relocateBatchState` and `document`
const selectRelocateShelf_live = new Function(
  'shelfId',
  'document',
  'relocateBatchState',
  selectRelocateShelfBody
);

// ── All 14 canonical shelf IDs ───────────────────────────────────────────────

const ALL_SHELF_IDS = [
  'Rack A1', 'Rack A2', 'Rack A3',
  'Rack B1', 'Rack B2', 'Rack B3',
  'Rack C1', 'Rack C2', 'Rack C3',
  'Rack D1', 'Rack D2', 'Rack D3',
  'Cold Storage F1', 'Cold Storage F2'
];

const ALL_SHELVES = [
  { id: 'Rack A1',         rack: 'RACK_A',    label: 'A1 - Fast Moving Analgesics',          zone: 'Front Left' },
  { id: 'Rack A2',         rack: 'RACK_A',    label: 'A2 - Pain & Anti-inflammatory',         zone: 'Front Left' },
  { id: 'Rack A3',         rack: 'RACK_A',    label: 'A3 - Antipyretics & Cold',              zone: 'Front Left' },
  { id: 'Rack B1',         rack: 'RACK_B',    label: 'B1 - Broad Spectrum Antibiotics',       zone: 'Front Right' },
  { id: 'Rack B2',         rack: 'RACK_B',    label: 'B2 - Cephalosporins',                   zone: 'Front Right' },
  { id: 'Rack B3',         rack: 'RACK_B',    label: 'B3 - Antifungals',                      zone: 'Front Right' },
  { id: 'Rack C1',         rack: 'RACK_C',    label: 'C1 - Cardiovascular & BP',              zone: 'Back Left' },
  { id: 'Rack C2',         rack: 'RACK_C',    label: 'C2 - Diabetes & Endocrine',             zone: 'Back Left' },
  { id: 'Rack C3',         rack: 'RACK_C',    label: 'C3 - Gastro & Antacids',                zone: 'Back Left' },
  { id: 'Rack D1',         rack: 'RACK_D',    label: 'D1 - Ointments & Creams',               zone: 'Back Right' },
  { id: 'Rack D2',         rack: 'RACK_D',    label: 'D2 - Eye & Ear Drops',                  zone: 'Back Right' },
  { id: 'Rack D3',         rack: 'RACK_D',    label: 'D3 - Inhalers & Respiratory',           zone: 'Back Right' },
  { id: 'Cold Storage F1', rack: 'RACK_COLD', label: 'Cold Bay F1 - Insulins',                zone: 'Cold Refrigerator' },
  { id: 'Cold Storage F2', rack: 'RACK_COLD', label: 'Cold Bay F2 - Vaccines & Sera',         zone: 'Cold Refrigerator' }
];

// ── Helper: build a minimal dialog DOM ───────────────────────────────────────

function makeDialogDOM() {
  return new JSDOM(`<!DOCTYPE html>
    <div id="relocate-map-grid"></div>
    <p  id="relocate-new-location" class="muted">Click a shelf on the map below</p>
    <button id="relocate-save-btn" disabled></button>
  `);
}

// ── CSS regression tests (Task 1–6) ─────────────────────────────────────────

test('CSS cascade: base button rule declares color: white (documents the cascade source)', () => {
  const css = fs.readFileSync(STYLES_PATH, 'utf8');
  const baseBlock = extractCssBlock(css, '\nbutton {');
  assert.ok(baseBlock !== null, 'Base button { } block must exist in styles.css');
  const colorVal = getColorValue(baseBlock);
  assert.equal(colorVal, 'white',
    'Base button rule must declare color: white — this is the cascade source of the bug. ' +
    'If this assertion fails, the base rule changed and this test file needs updating.');
});

test('CSS cascade fix: .relocate-shelf-btn explicitly declares color (overrides base button)', () => {
  const css = fs.readFileSync(STYLES_PATH, 'utf8');
  const block = extractCssBlock(css, '.relocate-shelf-btn {');
  assert.ok(block !== null, '.relocate-shelf-btn rule must exist in styles.css');

  assert.ok(hasColorDeclaration(block),
    '.relocate-shelf-btn must declare an explicit `color:` property to override ' +
    'the base `button { color: white }` cascade that made shelf buttons invisible.');
});

test('CSS cascade fix: .relocate-shelf-btn color is not white (buttons are now readable)', () => {
  const css = fs.readFileSync(STYLES_PATH, 'utf8');
  const block = extractCssBlock(css, '.relocate-shelf-btn {');
  assert.ok(block !== null, '.relocate-shelf-btn rule must exist');

  const colorVal = getColorValue(block);
  assert.ok(colorVal !== null, '.relocate-shelf-btn must have a color value');

  const WHITE_VALUES = ['white', '#fff', '#ffffff', 'rgb(255,255,255)', 'rgb(255, 255, 255)'];
  assert.equal(
    WHITE_VALUES.includes(colorVal), false,
    `.relocate-shelf-btn color must NOT be white. Got: "${colorVal}". ` +
    'White text on white background was the root cause of invisible shelf buttons.'
  );
});

test('CSS cascade fix: .relocate-shelf-btn:hover also declares color (prevents hover invisibility)', () => {
  const css = fs.readFileSync(STYLES_PATH, 'utf8');
  const block = extractCssBlock(css, '.relocate-shelf-btn:hover {');
  assert.ok(block !== null, '.relocate-shelf-btn:hover rule must exist in styles.css');

  assert.ok(hasColorDeclaration(block),
    '.relocate-shelf-btn:hover must declare `color:` to prevent the base ' +
    'button:hover rule from leaving text unreadable against --accent-light background.');
});

test('CSS: .relocate-shelf-btn.selected retains color: white (intentional — dark teal background)', () => {
  const css = fs.readFileSync(STYLES_PATH, 'utf8');
  const block = extractCssBlock(css, '.relocate-shelf-btn.selected {');
  assert.ok(block !== null, '.relocate-shelf-btn.selected rule must exist');

  const colorVal = getColorValue(block);
  const WHITE_VALUES = ['white', '#fff', '#ffffff'];
  assert.ok(WHITE_VALUES.includes(colorVal),
    `.relocate-shelf-btn.selected must keep color: white (readable against var(--accent) teal background). Got: "${colorVal}"`);
});

test('CSS: .relocate-shelf-btn.current-location does not set white or near-white text', () => {
  const css = fs.readFileSync(STYLES_PATH, 'utf8');
  const block = extractCssBlock(css, '.relocate-shelf-btn.current-location {');
  assert.ok(block !== null, '.relocate-shelf-btn.current-location rule must exist');

  // If a color IS declared, it must not be white (current-location has yellow bg #fff3cd).
  if (hasColorDeclaration(block)) {
    const colorVal = getColorValue(block);
    const WHITE_VALUES = ['white', '#fff', '#ffffff'];
    assert.equal(WHITE_VALUES.includes(colorVal), false,
      `.relocate-shelf-btn.current-location must not use white text against its yellow background. Got: "${colorVal}"`);
  }
  // If no color is declared, it will inherit from .relocate-shelf-btn which is now var(--ink) — fine.
});

// ── DOM regression tests (Task 7–14) ─────────────────────────────────────────

test('renderRelocateMap (jsdom): all 14 canonical shelf IDs render as buttons', async () => {
  const dom = makeDialogDOM();
  const { document } = dom.window;

  const storeMapData_ref = { current: { shelves: ALL_SHELVES, unassigned: { batches: [] } } };
  const relocateBatchState = { currentLocation: 'No shelf assigned' };

  await renderRelocateMap_live(document, storeMapData_ref, relocateBatchState, escapeHtml, async () => {});

  const buttons = document.querySelectorAll('[data-relocate-shelf]');
  assert.equal(buttons.length, 14,
    `Must render exactly 14 shelf buttons (one per canonical shelf). Got: ${buttons.length}`);

  const renderedIds = Array.from(buttons).map(b => b.dataset.relocateShelf);
  for (const expectedId of ALL_SHELF_IDS) {
    assert.ok(renderedIds.includes(expectedId),
      `Shelf button for "${expectedId}" must be rendered`);
  }
});

test('renderRelocateMap (jsdom): every button has a non-empty data-relocate-shelf attribute', async () => {
  const dom = makeDialogDOM();
  const { document } = dom.window;

  const storeMapData_ref = { current: { shelves: ALL_SHELVES, unassigned: { batches: [] } } };
  const relocateBatchState = { currentLocation: 'No shelf assigned' };

  await renderRelocateMap_live(document, storeMapData_ref, relocateBatchState, escapeHtml, async () => {});

  document.querySelectorAll('[data-relocate-shelf]').forEach(btn => {
    assert.ok(btn.dataset.relocateShelf && btn.dataset.relocateShelf.trim().length > 0,
      `Button must have non-empty data-relocate-shelf. Got: "${btn.dataset.relocateShelf}"`);
  });
});

test('renderRelocateMap (jsdom): button text content matches shelf ID (not blank)', async () => {
  const dom = makeDialogDOM();
  const { document } = dom.window;

  const storeMapData_ref = { current: { shelves: ALL_SHELVES, unassigned: { batches: [] } } };
  const relocateBatchState = { currentLocation: 'No shelf assigned' };

  await renderRelocateMap_live(document, storeMapData_ref, relocateBatchState, escapeHtml, async () => {});

  document.querySelectorAll('[data-relocate-shelf]').forEach(btn => {
    const text = btn.textContent.trim();
    const shelfId = btn.dataset.relocateShelf;
    assert.ok(text.length > 0,
      `Button for "${shelfId}" must have non-empty text content (invisible text was the bug)`);
    assert.ok(text.includes(shelfId),
      `Button text must include the shelf ID "${shelfId}". Got: "${text}"`);
  });
});

test('renderRelocateMap (jsdom): all 5 rack groups are rendered with data-rack attribute', async () => {
  const dom = makeDialogDOM();
  const { document } = dom.window;

  const storeMapData_ref = { current: { shelves: ALL_SHELVES, unassigned: { batches: [] } } };
  const relocateBatchState = { currentLocation: 'No shelf assigned' };

  await renderRelocateMap_live(document, storeMapData_ref, relocateBatchState, escapeHtml, async () => {});

  const expectedRacks = ['RACK_A', 'RACK_B', 'RACK_C', 'RACK_D', 'RACK_COLD'];
  for (const rack of expectedRacks) {
    const card = document.querySelector(`[data-rack="${rack}"]`);
    assert.ok(card !== null, `Rack card with data-rack="${rack}" must be rendered`);
  }
  const allRackCards = document.querySelectorAll('[data-rack]');
  assert.equal(allRackCards.length, expectedRacks.length,
    `Must render exactly ${expectedRacks.length} rack cards. Got: ${allRackCards.length}`);
});

test('renderRelocateMap (jsdom): each rack card contains only its own shelves', async () => {
  const dom = makeDialogDOM();
  const { document } = dom.window;

  const storeMapData_ref = { current: { shelves: ALL_SHELVES, unassigned: { batches: [] } } };
  const relocateBatchState = { currentLocation: 'No shelf assigned' };

  await renderRelocateMap_live(document, storeMapData_ref, relocateBatchState, escapeHtml, async () => {});

  const rackToShelves = {};
  for (const shelf of ALL_SHELVES) {
    if (!rackToShelves[shelf.rack]) rackToShelves[shelf.rack] = [];
    rackToShelves[shelf.rack].push(shelf.id);
  }

  for (const [rack, shelves] of Object.entries(rackToShelves)) {
    const card = document.querySelector(`[data-rack="${rack}"]`);
    assert.ok(card, `Rack card for ${rack} must exist`);
    const btns = card.querySelectorAll('[data-relocate-shelf]');
    assert.equal(btns.length, shelves.length,
      `Rack ${rack} must contain ${shelves.length} shelf buttons. Got: ${btns.length}`);
    btns.forEach(btn => {
      assert.ok(shelves.includes(btn.dataset.relocateShelf),
        `Shelf "${btn.dataset.relocateShelf}" must belong to rack ${rack}`);
    });
  }
});

test('renderRelocateMap (jsdom): current-location class applied to matching shelf only', async () => {
  const dom = makeDialogDOM();
  const { document } = dom.window;

  const storeMapData_ref = { current: { shelves: ALL_SHELVES, unassigned: { batches: [] } } };
  const relocateBatchState = { currentLocation: 'Rack C2' };

  await renderRelocateMap_live(document, storeMapData_ref, relocateBatchState, escapeHtml, async () => {});

  const allButtons = document.querySelectorAll('[data-relocate-shelf]');

  let currentCount = 0;
  allButtons.forEach(btn => {
    const shelfId = btn.dataset.relocateShelf;
    if (btn.classList.contains('current-location')) {
      currentCount++;
      assert.equal(shelfId, 'Rack C2',
        `Only "Rack C2" should have current-location class. Got: "${shelfId}"`);
    }
  });

  assert.equal(currentCount, 1,
    `Exactly 1 button should have current-location class. Got: ${currentCount}`);
});

test('renderRelocateMap (jsdom): no shelf is pre-selected on open', async () => {
  const dom = makeDialogDOM();
  const { document } = dom.window;

  const storeMapData_ref = { current: { shelves: ALL_SHELVES, unassigned: { batches: [] } } };
  const relocateBatchState = { currentLocation: 'Rack A1' };

  await renderRelocateMap_live(document, storeMapData_ref, relocateBatchState, escapeHtml, async () => {});

  const selectedButtons = document.querySelectorAll('[data-relocate-shelf].selected');
  assert.equal(selectedButtons.length, 0,
    'No shelf button should be pre-selected when the dialog opens');

  const saveBtn = document.querySelector('#relocate-save-btn');
  assert.equal(saveBtn.disabled, true,
    'Save button must be disabled until user selects a destination shelf');
});

test('selectRelocateShelf (jsdom): adds selected class and enables Save button', () => {
  // This test exercises selectRelocateShelf() directly to prove that selecting
  // a shelf highlights it and gates the Save button correctly.
  const dom = new JSDOM(`<!DOCTYPE html>
    <div id="relocate-map-grid">
      <button data-relocate-shelf="Rack B1" class="relocate-shelf-btn">Rack B1</button>
      <button data-relocate-shelf="Rack B2" class="relocate-shelf-btn">Rack B2</button>
      <button data-relocate-shelf="Rack B3" class="relocate-shelf-btn">Rack B3</button>
    </div>
    <p id="relocate-new-location" class="muted">Click a shelf on the map below</p>
    <button id="relocate-save-btn" disabled></button>
  `);
  const { document } = dom.window;
  const relocateBatchState = {};

  // Select Rack B2
  selectRelocateShelf_live('Rack B2', document, relocateBatchState);

  assert.equal(relocateBatchState.selectedShelfId, 'Rack B2',
    'selectRelocateShelf must set relocateBatchState.selectedShelfId');

  const saveBtn = document.querySelector('#relocate-save-btn');
  assert.equal(saveBtn.disabled, false,
    'Save button must be enabled after a shelf is selected');

  const newLocEl = document.querySelector('#relocate-new-location');
  assert.equal(newLocEl.textContent, 'Rack B2',
    '#relocate-new-location must show the selected shelf ID');
  assert.equal(newLocEl.classList.contains('muted'), false,
    '#relocate-new-location must lose the muted class when a shelf is selected');

  const b2btn = document.querySelector('[data-relocate-shelf="Rack B2"]');
  assert.ok(b2btn.classList.contains('selected'),
    'Selected shelf button must have the "selected" class');

  const b1btn = document.querySelector('[data-relocate-shelf="Rack B1"]');
  assert.equal(b1btn.classList.contains('selected'), false,
    'Non-selected shelf button must NOT have the "selected" class');
});

test('selectRelocateShelf (jsdom): re-selecting a different shelf moves the highlight', () => {
  const dom = new JSDOM(`<!DOCTYPE html>
    <div id="relocate-map-grid">
      <button data-relocate-shelf="Rack D1" class="relocate-shelf-btn">Rack D1</button>
      <button data-relocate-shelf="Rack D2" class="relocate-shelf-btn">Rack D2</button>
    </div>
    <p id="relocate-new-location" class="muted"></p>
    <button id="relocate-save-btn" disabled></button>
  `);
  const { document } = dom.window;
  const relocateBatchState = {};

  selectRelocateShelf_live('Rack D1', document, relocateBatchState);
  assert.equal(document.querySelector('[data-relocate-shelf="Rack D1"]').classList.contains('selected'), true);
  assert.equal(document.querySelector('[data-relocate-shelf="Rack D2"]').classList.contains('selected'), false);

  // Re-select D2 — highlight must move
  selectRelocateShelf_live('Rack D2', document, relocateBatchState);
  assert.equal(relocateBatchState.selectedShelfId, 'Rack D2', 'State must update to Rack D2');
  assert.equal(document.querySelector('[data-relocate-shelf="Rack D2"]').classList.contains('selected'), true,
    'Rack D2 must gain selected class');
  assert.equal(document.querySelector('[data-relocate-shelf="Rack D1"]').classList.contains('selected'), false,
    'Rack D1 must lose selected class');
});
